Require Import ZArith List Lia.
Import ListNotations.
Open Scope Z_scope.

Definition mat := nat -> nat -> Z.
Definition vec := nat -> Z.
Definition sum (n:nat) (f:nat->Z) : Z := fold_right Z.add 0 (map f (seq 0 n)).

Lemma fold_shift : forall (l:list Z) c, fold_right Z.add c l = fold_right Z.add 0 l + c.
Proof. induction l; intros c; simpl; [ring|]. rewrite IHl. rewrite (IHl 0). ring. Qed.

Lemma sum_S : forall n f, sum (S n) f = sum n f + f n.
Proof.
  intros n f. unfold sum. rewrite seq_S, map_app, fold_right_app. simpl.
  rewrite fold_shift. ring.
Qed.

Lemma sum_0 : forall f, sum 0 f = 0.
Proof. intros. reflexivity. Qed.

Lemma sum_ext : forall n f g, (forall k, (k < n)%nat -> f k = g k) -> sum n f = sum n g.
Proof.
  induction n; intros f g H. reflexivity.
  rewrite !sum_S, H by lia. f_equal. apply IHn. intros; apply H; lia.
Qed.

Lemma sum_zero : forall n, sum n (fun _ => 0) = 0.
Proof. induction n. reflexivity. rewrite sum_S, IHn. ring. Qed.

Lemma sum_scal : forall n c f, sum n (fun k => c * f k) = c * sum n f.
Proof. induction n; intros. rewrite !sum_0; ring. rewrite !sum_S, IHn. ring. Qed.

Lemma sum_plus : forall n f g, sum n (fun k => f k + g k) = sum n f + sum n g.
Proof. induction n; intros. rewrite !sum_0; ring. rewrite !sum_S, IHn. ring. Qed.

Lemma sum_swap : forall n m f,
  sum n (fun i => sum m (fun j => f i j)) = sum m (fun j => sum n (fun i => f i j)).
Proof.
  induction n; intros m f.
  - rewrite sum_0. rewrite <- (sum_zero m). apply sum_ext. intros. reflexivity.
  - rewrite sum_S, IHn, <- sum_plus. apply sum_ext. intros j _. rewrite sum_S. reflexivity.
Qed.

(* the only delta we need: a sum against a Kronecker row collapses *)
Lemma sum_delta : forall n (d:Z) (c:nat->Z) i, (i < n)%nat ->
  sum n (fun k => (if Nat.eqb i k then d else 0) * c k) = d * c i.
Proof.
  induction n; intros d c i Hi. lia.
  rewrite sum_S. destruct (Nat.eq_dec i n) as [->|Hne].
  - rewrite Nat.eqb_refl.
    rewrite (sum_ext n (fun k => (if Nat.eqb n k then d else 0) * c k) (fun _ => 0)).
    + rewrite sum_zero. ring.
    + intros k Hk. destruct (Nat.eqb_spec n k); [lia|ring].
  - destruct (Nat.eqb_spec i n); [lia|]. rewrite IHn by lia. ring.
Qed.

Definition mmul (n:nat) (A B:mat) : mat := fun i j => sum n (fun k => A i k * B k j).
Definition mvec (n:nat) (A:mat) (v:vec) : vec := fun i => sum n (fun k => A i k * v k).

Lemma mvec_assoc : forall n A B v i,
  mvec n (mmul n A B) v i = mvec n A (mvec n B v) i.
Proof.
  intros n A B v i. unfold mvec, mmul.
  rewrite (sum_ext n (fun k => sum n (fun l => A i l * B l k) * v k)
                     (fun k => sum n (fun l => A i l * B l k * v k)))
    by (intros k Hk;
        transitivity (sum n (fun l => v k * (A i l * B l k)));
        [ rewrite sum_scal; ring | apply sum_ext; intros; ring ]).
  rewrite sum_swap.
  apply sum_ext. intros l _.
  transitivity (sum n (fun k => A i l * (B l k * v k))).
  - apply sum_ext. intros; ring.
  - apply sum_scal.
Qed.

