Definition W22 : mat := cm W8 W6.
Definition W23 : mat := cm W8 W7.
Definition W24 : mat := cm W9 W3.
Definition W25 : mat := cm W9 W4.

Definition WL : list mat := [W1;W2;W3;W4;W5;W6;W7;W8;W9;W10;W11;W12;W13;W14;W15;W16;W17;W18;W19;W20;W21;W22;W23;W24;W25].

(* column k of M is the 5x5 word W(k+1) read row-major *)
Definition Mfun : mat :=
  fun p k => nth k WL (fun _ _ => 0) (Nat.div p 5) (Nat.modulo p 5).
Definition Mlist : list (list Z) :=
  map (fun p => map (fun k => Mfun p k) (seq 0 25)) (seq 0 25).

