Definition kron (i j:nat) : Z := if Nat.eqb i j then DET else 0.

Definition chk (A C:mat) : bool :=
  forallb (fun i => forallb (fun j => Z.eqb (mmul 25 A C i j) (kron i j)) (seq 0 25))
          (seq 0 25).

Theorem M_ADJ : chk M ADJ = true.
Proof. vm_compute. reflexivity. Qed.

Theorem ADJ_M : chk ADJ M = true.
Proof. vm_compute. reflexivity. Qed.

Theorem DET_nonzero : DET <> 0.
Proof. unfold DET. discriminate. Qed.

Lemma chk_pt : forall A C, chk A C = true ->
  forall i j, (i < 25)%nat -> (j < 25)%nat -> mmul 25 A C i j = kron i j.
Proof.
  intros A C H i j Hi Hj. unfold chk in H.
  rewrite forallb_forall in H.
  assert (Hin : In i (seq 0 25)) by (apply in_seq; lia).
  specialize (H i Hin). rewrite forallb_forall in H.
  assert (Hjn : In j (seq 0 25)) by (apply in_seq; lia).
  specialize (H j Hjn).
  now apply Z.eqb_eq in H.
Qed.

(* ---- INDEPENDENCE: the 25 words are linearly independent ---- *)
Theorem words_independent :
  forall c:vec, (forall i, (i < 25)%nat -> mvec 25 M c i = 0) ->
  forall k, (k < 25)%nat -> c k = 0.
Proof.
  intros c Hz k Hk.
  assert (E : DET * c k = 0).
  { transitivity (sum 25 (fun j => kron k j * c j)).
     - unfold kron. rewrite sum_delta by exact Hk. reflexivity.
     - transitivity (mvec 25 (mmul 25 ADJ M) c k).
       + unfold mvec. apply sum_ext. intros j Hj.
         f_equal. symmetry. exact (chk_pt ADJ M ADJ_M k j Hk Hj).
       + rewrite mvec_assoc. unfold mvec.
         rewrite (sum_ext 25
                    (fun j => ADJ k j * sum 25 (fun l => M j l * c l))
                    (fun _ => 0)).
         * apply sum_zero.
         * intros j Hj. specialize (Hz j Hj). unfold mvec in Hz.
           rewrite Hz. ring. }
  apply Z.mul_eq_0 in E. destruct E as [E|E].
  - exfalso. now apply DET_nonzero.
  - exact E.
Qed.

(* ---- SPANNING: every target is reached, with explicit coefficients ---- *)
Theorem words_span :
  forall v:vec, forall k, (k < 25)%nat ->
  mvec 25 M (mvec 25 ADJ v) k = DET * v k.
Proof.
  intros v k Hk. rewrite <- mvec_assoc. unfold mvec.
  transitivity (sum 25 (fun j => kron k j * v j)).
  - apply sum_ext. intros j Hj. f_equal. exact (chk_pt M ADJ M_ADJ k j Hk Hj).
  - unfold kron. now rewrite sum_delta.
Qed.
